mapper.select:
SELECT r.reg_id AS regId, r.project_id AS projectId, r.student_id AS studentId, r.class_id AS classId, r.real_name AS realName, r.gender AS gender, r.birth_date AS birthDate, r.id_card AS idCard, r.phone AS phone, r.material_url AS materialUrl, r.teacher_id AS teacherId, r.teacher_comment AS teacherComment, r.status AS status, r.audit_remark AS auditRemark, r.exam_time AS examTime, r.exam_room AS examRoom, r.seat_no AS seatNo, r.result AS result, r.award AS award, r.certificate_no AS certificateNo, r.create_time AS createTime, p.name AS projectName, p.activity_type AS activityType, p.category AS category, p.organizer AS organizer, p.exam_date AS examDate, p.location AS projectLocation, p.exam_start AS projectExamStart, p.exam_end AS projectExamEnd, p.exam_room AS projectExamRoom, p.fee AS fee, p.requirement AS requirement, p.award_desc AS awardDesc, p.materials AS materials, s.student_no AS studentNo, s.name AS studentName, cc.class_name AS className, t.name AS teacherName FROM exam_registration r JOIN exam_project p ON p.project_id=r.project_id LEFT JOIN student s ON s.student_id=r.student_id LEFT JOIN course_class cc ON cc.class_id=r.class_id LEFT JOIN teacher t ON t.teacher_id=r.teacher_id
AND r.project_id=#{projectId} AND r.student_id=#{studentId} AND r.status=#{status} AND p.activity_type=#{activityType}
ORDER BY r.reg_id DESC


AND r.student_id = #{studentId}
AND p.activity_type = #{activityType}
ORDER BY p.exam_date DESC, r.reg_id DESC


AND r.class_id = #{classId}
AND p.activity_type = #{activityType}
ORDER BY p.exam_date DESC, r.reg_id DESC
